// stream abandoned before io.EOF.
func (s ThreadServiceSubscribeClientStream) Close() error {
	return s.stream.Close()
}

// ThreadServiceHandler is an implementation of the inaba.v1.ThreadService service.
type ThreadServiceHandler interface {
	ListProviders(context.Context, *v1.ListProvidersRequest) (*v1.ListProvidersResponse, error)
	CreateThread(context.Context, *v1.CreateThreadRequest) (*v1.Thread, error)
	ListThreads(context.Context, *v1.ListThreadsRequest) (*v1.ListThreadsResponse, error)
	GetThread(context.Context, *v1.GetThreadRequest) (*v1.Thread, error)
	// Renames the thread.
	UpdateThread(context.Context, *v1.UpdateThreadRequest) (*v1.Thread, error)
	// Stops the thread's process and forgets the thread.
	DeleteThread(context.Context, *v1.DeleteThreadRequest) (*v1.DeleteThreadResponse, error)
	// Starts a turn with the message, or queues the message when a turn is running.
	// Queued messages run in order, each as its own turn, once the turns before them end.
	StartTurn(context.Context, *v1.StartTurnRequest) (*v1.StartTurnResponse, error)
	// Stops the running turn and pauses the queue.
	Interrupt(context.Context, *v1.InterruptRequest) (*v1.InterruptResponse, error)
	// Changes one of the thread's options. Fails while the agent is not running.
	SetOption(context.Context, *v1.SetOptionRequest) (*v1.Thread, error)
	// Takes a message out of the queue.
	CancelQueued(context.Context, *v1.CancelQueuedRequest) (*v1.Thread, error)
	// Changes the text of a message still waiting in the queue.
	EditQueued(context.Context, *v1.EditQueuedRequest) (*v1.Thread, error)
	// Puts a waiting message at another place in the queue.
	MoveQueued(context.Context, *v1.MoveQueuedRequest) (*v1.Thread, error)
	// Runs a waiting message next: it goes to the head of the queue, the running turn
	// is stopped as StartTurn with interrupt does, and a paused queue goes again.
	SendQueuedNow(context.Context, *v1.SendQueuedNowRequest) (*v1.Thread, error)
	// Lets a paused queue run again.
	ResumeQueue(context.Context, *v1.ResumeQueueRequest) (*v1.Thread, error)
	// Answers a permission request.
	Respond(context.Context, *v1.RespondRequest) (*v1.RespondResponse, error)
	// Restarts the thread's process in the other mode, resuming the same native session.
	// State held only by the old process is lost. Fails while a turn is running.
	SetMode(context.Context, *v1.SetModeRequest) (*v1.Thread, error)
	// Sends a request of the provider's own protocol and returns its result unchanged.
	Raw(context.Context, *v1.RawRequest) (*v1.RawResponse, error)
	// Takes the conversation back to before one of the user's messages, which is
	// answered so it can be edited and sent again. Only while no turn is running. The
	// events stay in the log, after a Rewound event that marks them as taken back.
	Rewind(context.Context, *v1.RewindRequest) (*v1.RewindResponse, error)
	// Starts a new thread that carries this one's conversation through the end of the
	// turn holding seq. Its agent session is new: like after Rewind, the first turn
	// hands it the conversation. A thread with a worktree of its own forks into a new
	// worktree, from the commit the original is on; uncommitted changes stay behind.
	// Saves the thread's screen layout for everyone in it and tells them.
	SetLayout(context.Context, *v1.SetLayoutRequest) (*v1.Thread, error)
	ForkThread(context.Context, *v1.ForkThreadRequest) (*v1.Thread, error)
	ListEvents(context.Context, *v1.ListEventsRequest) (*v1.ListEventsResponse, error)
	// A file attached to one of the thread's messages, by the message's event and the
	// file's place among its attachments. Subscribe leaves images' bytes out; this is
	// where they come from.
	GetAttachment(context.Context, *v1.GetAttachmentRequest) (*v1.Attachment, error)
	// What one agent of a background workflow the thread's agent started has done so far.
	GetWorkflowAgent(context.Context, *v1.GetWorkflowAgentRequest) (*v1.GetWorkflowAgentResponse, error)
	// The agent's conversation again whenever it grows, until the agent is done.
	WatchWorkflowAgent(context.Context, *v1.GetWorkflowAgentRequest, ThreadServiceWatchWorkflowAgentServerStream) error
	// Sends every event after after_seq, then new ones as they happen.
	// The events after after_seq, then each as it happens. To stay light for a thread
	// that is opened often, it leaves out what ListEvents carries for the record: a tool
	// call's or permission request's raw, and an attached image's data (its size is set
	// instead; GetAttachment has it).
	Subscribe(context.Context, *v1.SubscribeRequest, ThreadServiceSubscribeServerStream) error
}

// RegisterThreadServiceHandler registers svc as the inaba.v1.ThreadService implementation on
// server.
func RegisterThreadServiceHandler(server *connect.Server, svc ThreadServiceHandler) {
	adapter := threadServiceHandler{svc: svc}
	server.Register(
		connect.Method{Spec: threadServiceListProvidersSpec(), Handler: adapter.listProviders},
		connect.Method{Spec: threadServiceCreateThreadSpec(), Handler: adapter.createThread},
		connect.Method{Spec: threadServiceListThreadsSpec(), Handler: adapter.listThreads},
		connect.Method{Spec: threadServiceGetThreadSpec(), Handler: adapter.getThread},
		connect.Method{Spec: threadServiceUpdateThreadSpec(), Handler: adapter.updateThread},
		connect.Method{Spec: threadServiceDeleteThreadSpec(), Handler: adapter.deleteThread},
		connect.Method{Spec: threadServiceStartTurnSpec(), Handler: adapter.startTurn},
		connect.Method{Spec: threadServiceInterruptSpec(), Handler: adapter.interrupt},
		connect.Method{Spec: threadServiceSetOptionSpec(), Handler: adapter.setOption},
		connect.Method{Spec: threadServiceCancelQueuedSpec(), Handler: adapter.cancelQueued},
		connect.Method{Spec: threadServiceEditQueuedSpec(), Handler: adapter.editQueued},
		connect.Method{Spec: threadServiceMoveQueuedSpec(), Handler: adapter.moveQueued},
		connect.Method{Spec: threadServiceSendQueuedNowSpec(), Handler: adapter.sendQueuedNow},
		connect.Method{Spec: threadServiceResumeQueueSpec(), Handler: adapter.resumeQueue},
		connect.Method{Spec: threadServiceRespondSpec(), Handler: adapter.respond},
		connect.Method{Spec: threadServiceSetModeSpec(), Handler: adapter.setMode},
		connect.Method{Spec: threadServiceRawSpec(), Handler: adapter.raw},
		connect.Method{Spec: threadServiceRewindSpec(), Handler: adapter.rewind},
		connect.Method{Spec: threadServiceSetLayoutSpec(), Handler: adapter.setLayout},
		connect.Method{Spec: threadServiceForkThreadSpec(), Handler: adapter.forkThread},
		connect.Method{Spec: threadServiceListEventsSpec(), Handler: adapter.listEvents},
		connect.Method{Spec: threadServiceGetAttachmentSpec(), Handler: adapter.getAttachment},
		connect.Method{Spec: threadServiceGetWorkflowAgentSpec(), Handler: adapter.getWorkflowAgent},
		connect.Method{Spec: threadServiceWatchWorkflowAgentSpec(), Handler: adapter.watchWorkflowAgent},
		connect.Method{Spec: threadServiceSubscribeSpec(), Handler: adapter.subscribe},
	)
}

