// GitServiceClient is a client for the inaba.v1.GitService service.
type GitServiceClient interface {
	GetStatus(context.Context, *v1.GetGitStatusRequest) (*v1.GitStatus, error)
	// The uncommitted changes as a unified diff, of one file or of everything.
	GetDiff(context.Context, *v1.GetGitDiffRequest) (*v1.GetGitDiffResponse, error)
	ListBranches(context.Context, *v1.ListBranchesRequest) (*v1.ListBranchesResponse, error)
	// Switches the folder to a branch, creating it first when asked to. Refused while a
	// thread is running a turn in that folder.
	Checkout(context.Context, *v1.GitCheckoutRequest) (*v1.GitStatus, error)
	// Puts the thread's files back as they were at a snapshot from a TurnChanges event.
	// Only for a thread with a worktree of its own, where no other thread's work can
	// be lost, and not while a turn is running. The files as they were just before the
	// restore are snapshotted too, so it can be undone. The conversation is not changed.
	Restore(context.Context, *v1.GitRestoreRequest) (*v1.GitRestoreResponse, error)
	// Pushes the branch, setting its upstream on origin when it has none.
	Push(context.Context, *v1.GitPushRequest) (*v1.GitCommitResponse, error)
	// Fetches from the remote (git fetch), so the status's ahead and behind are current.
	// The files are not touched.
	Fetch(context.Context, *v1.GitFetchRequest) (*v1.GitCommitResponse, error)
	// Brings the current branch up to its upstream with git pull --ff-only. Refused while
	// a thread is running a turn in that folder, and when the branch has diverged from
	// its upstream or local changes are in the way: nothing is merged or rebased.
	Pull(context.Context, *v1.GitPullBranchRequest) (*v1.GitCommitResponse, error)
	// Opens a GitHub pull request for the current branch with the GitHub CLI (gh) on
	// the host, pushing the branch first when the remote is behind it. When the branch
	// already has an open pull request, that one is answered instead of a new one.
	// Uncommitted changes are not part of it.
	CreatePullRequest(context.Context, *v1.GitPullRequestRequest) (*v1.GitPullRequestResponse, error)
	// Commits every change in the working tree, and pushes when asked to.
	Commit(context.Context, *v1.GitCommitRequest) (*v1.GitCommitResponse, error)
}

// NewGitServiceClient constructs a client for the inaba.v1.GitService service. Multiple service
// clients may share a single connect.Client.
func NewGitServiceClient(client *connect.Client) GitServiceClient {
	return &gitServiceClient{client: client}
}

